input.content:
/* Margin, Issue 14: Low Water */

@property --tide {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 74%;
}

:root {
  --paper: #f2ede2;
  --ink: #1d1b18;
  --ink-soft: #4d4940;
  --rule: #8c8576;
  --accent: #9b4a1f;
  --measure: 36rem;
  --gutter: clamp(1.25rem, 5vw, 3.5rem);
  --body-size: 1.0625rem;
  --body-leading: 1.6;
  --lede-size: clamp(1.2rem, 2.2vw, 1.5rem);
  --font-serif: Charter, "Bitstream Charter", "Sitka Text", Cambria, Georgia, "Times New Roman", serif;
  --font-sans: "Helvetica Neue", Helvetica, Arial, "Liberation Sans", sans-serif;
  color-scheme: light;
}

/* Reading mode: larger text, looser leading, narrower measure, quieter art. */
.reading-mode {
  --body-size: 1.3125rem;
  --body-leading: 1.75;
  --lede-size: 1.6rem;
  --measure: 34em;
  --ink-soft: #2e2b25;
  --rule: #6d675b;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  background: var(--paper);
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-serif);
  font-size: var(--body-size);
  line-height: var(--body-leading);
  font-kerning: normal;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3,
p,
ol,
ul,
dl,
dd {
  margin: 0;
}

a {
  color: inherit;
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  top: -4rem;
  left: var(--gutter);
  z-index: 10;
  padding: 0.5rem 0.9rem;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--font-sans);
  font-size: 0.9rem;
  text-decoration: none;
}

.skip-link:focus {
  top: 0.75rem;
}

.wrap {
  width: calc(100% - (2 * var(--gutter)));
  max-width: 76rem;
  margin-inline: auto;
}

/* Shared small-caps labels and the display wordmark. */
.kicker,
.label,
.byline,
.story__byline,
.story__num,
.nav-list,
.reading-toggle,
.field__label,
.button,
.offer dt,
.archive__issue {
  font-family: var(--font-sans);
}

.kicker,
.label,
.offer dt,
.archive__issue {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.wordmark {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 6vw, 2.75rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1;
  color: var(--ink);
  text-decoration: none;
}

/* Masthead */
.masthead {
  border-bottom: 3px solid var(--ink);
}

.masthead__inner {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas:
    "brand toggle"
    "nav nav";
  align-items: center;
  gap: 0.9rem 1rem;
  padding-block: 1.1rem 0.9rem;
}

.masthead__brand {
  grid-area: brand;
}

.masthead__nav {
  grid-area: nav;
  padding-top: 0.7rem;
  border-top: 1px solid var(--rule);
}

.reading-toggle {
  grid-area: toggle;
  justify-self: end;
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.4rem 0.7rem 0.4rem 0.6rem;
  border: 1px solid var(--ink);
  background: transparent;
  color: var(--ink);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
}

.reading-toggle__track {
  position: relative;
  width: 2.25rem;
  height: 1.125rem;
  border: 1px solid var(--ink);
  transition: background-color 0.2s;
}

.reading-toggle__knob {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 0.75rem;
  height: 0.75rem;
  background: var(--ink);
  transition: transform 0.2s, background-color 0.2s;
}

.reading-toggle[aria-pressed="true"] .reading-toggle__track {
  background: var(--ink);
}

.reading-toggle[aria-pressed="true"] .reading-toggle__knob {
  background: var(--paper);
  transform: translateX(1.125rem);
}

.nav-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem 1.4rem;
  padding: 0;
  list-style: none;
  font-size: 0.8rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.nav-list a {
  color: var(--ink);
  text-decoration: none;
  padding-block: 0.2rem;
  background-image: linear-gradient(currentColor, currentColor);
  background-position: 0 100%;
  background-repeat: no-repeat;
  background-size: 0 1px;
  transition: background-size 0.2s;
}

.nav-list a:hover {
  background-size: 100% 1px;
}

@media (min-width: 760px) {
  .masthead__inner {
    grid-template-columns: auto 1fr auto;
    grid-template-areas: "brand nav toggle";
  }

  .masthead__nav {
    padding-top: 0;
    border-top: 0;
  }

  .nav-list {
    justify-content: center;
  }
}

/* Cover */
.cover {
  padding-block: clamp(1.25rem, 3vw, 2rem) clamp(3rem, 7vw, 6rem);
}

.cover__meta {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.4rem 1.5rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--ink);
}

.cover__grid {
  display: grid;
  gap: 2rem;
  margin-top: clamp(1.75rem, 4vw, 3rem);
}

/* One display motif: the title is cut by a waterline that drops into place. */
.display {
  font-family: var(--font-serif);
  font-size: clamp(4.75rem, 24vw, 15.5rem);
  font-weight: 700;
  line-height: 0.82;
  letter-spacing: -0.04em;
  color: var(--ink);
}

@supports ((-webkit-background-clip: text) or (background-clip: text)) {
  .display--tide {
    --tide: 74%;
    color: transparent;
    -webkit-background-clip: text;
    background-clip: text;
    background-image: linear-gradient(
      to bottom,
      var(--ink) 0 calc(var(--tide) - 0.5%),
      var(--paper) calc(var(--tide) - 0.5%) calc(var(--tide) + 0.5%),
      var(--accent) calc(var(--tide) + 0.5%) 100%
    );
  }
}

@supports (syntax: "<percentage>") {
  @media (prefers-reduced-motion: no-preference) {
    .display--tide {
      animation: tide-recede 2.4s cubic-bezier(0.2, 0.7, 0.2, 1) both;
    }
  }
}

@keyframes tide-recede {
  from {
    --tide: 58%;
  }

  to {
    --tide: 74%;
  }
}

.cover__deck {
  max-width: var(--measure);
  font-size: var(--lede-size);
  font-style: italic;
  line-height: 1.45;
}

.cover__art {
  justify-self: end;
  width: min(100%, 22rem);
}

.strata {
  display: block;
  width: 100%;
  height: auto;
  overflow: hidden;
  color: var(--ink);
}

.strata__line,
.strata__text,
.strata__plan {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.25;
}

.strata__text {
  stroke-width: 1;
}

.strata__plan {
  stroke-dasharray: 6 4;
}

.strata__tide {
  fill: none;
  stroke: var(--accent);
  stroke-width: 3.5;
}

.strata__margin {
  stroke: var(--accent);
  stroke-width: 1;
}

.strata__slip,
.strata__cap {
  fill: var(--paper);
  stroke: currentColor;
  stroke-width: 1.25;
}

.strata__crimp {
  fill: none;
  stroke: currentColor;
  stroke-width: 1;
  stroke-dasharray: 1.5 2.5;
}

.cover-story {
  display: grid;
  gap: 1rem 2rem;
  margin-top: clamp(2.5rem, 6vw, 4.5rem);
  padding-top: 1.25rem;
  border-top: 3px solid var(--ink);
}

.cover-story h2 {
  font-size: clamp(2.1rem, 5vw, 3.6rem);
  font-weight: 700;
  line-height: 1.02;
  letter-spacing: -0.02em;
  text-wrap: balance;
}

.cover-story .byline {
  margin-top: 0.85rem;
  font-size: 0.9rem;
  color: var(--ink-soft);
}

.cover-story .lede {
  margin-top: 1rem;
  max-width: var(--measure);
  font-size: var(--lede-size);
  line-height: 1.5;
}

@media (min-width: 900px) {
  .cover__grid {
    grid-template-columns: repeat(12, minmax(0, 1fr));
    column-gap: 1.5rem;
    align-items: start;
  }

  .display {
    grid-column: 1 / span 8;
  }

  .cover__deck {
    grid-column: 1 / span 5;
    align-self: end;
  }

  .cover__art {
    grid-column: 9 / span 4;
    grid-row: 1 / span 2;
    justify-self: stretch;
    width: auto;
  }

  .cover-story {
    grid-column: 1 / -1;
    grid-template-columns: repeat(12, minmax(0, 1fr));
    column-gap: 1.5rem;
  }

  .cover-story > .label {
    grid-column: 1 / span 3;
  }

  .cover-story__body {
    grid-column: 4 / span 7;
  }
}

/* Stories */
.stories {
  padding-block: clamp(3rem, 7vw, 5.5rem);
  border-top: 1px solid var(--ink);
}

.stories .label {
  margin-bottom: 0.6rem;
}

.section-title {
  font-size: clamp(2.2rem, 5vw, 3.6rem);
  font-weight: 700;
  line-height: 1.02;
  letter-spacing: -0.02em;
  text-wrap: balance;
}

.story-list {
  display: grid;
  gap: 2.75rem;
  margin-top: clamp(2rem, 5vw, 3rem);
  padding: 0;
  list-style: none;
}

.story {
  padding-top: 1rem;
  border-top: 1px solid var(--ink);
}

.story__num {
  margin-bottom: 0.6rem;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--accent);
}

.story__title {
  margin-bottom: 0.45rem;
  font-size: clamp(1.7rem, 3.4vw, 2.3rem);
  font-weight: 700;
  line-height: 1.08;
  letter-spacing: -0.01em;
  text-wrap: balance;
}

.story__byline {
  margin-bottom: 0.75rem;
  font-size: 0.85rem;
  color: var(--ink-soft);
}

.story__summary {
  max-width: var(--measure);
}

@media (min-width: 900px) {
  .story-list {
    grid-template-columns: repeat(12, minmax(0, 1fr));
    column-gap: 1.5rem;
    row-gap: 3.5rem;
    align-items: start;
  }

  .story--lead {
    grid-column: 1 / span 6;
  }

  .story--lead .story__title {
    font-size: clamp(2.6rem, 5vw, 4rem);
  }

  .story--second {
    grid-column: 8 / span 5;
    margin-top: 7rem;
  }

  .story--third {
    grid-column: 3 / span 7;
  }
}

/* Subscribe: the one inverted block. Variables are swapped so children inherit the dark palette. */
.subscribe {
  --paper: #1d1b18;
  --ink: #f2ede2;
  --ink-soft: #cbc3b0;
  --rule: #6e685c;
  --accent: #e8a878;
  padding-block: clamp(3.5rem, 8vw, 6rem);
  background: var(--paper);
  color: var(--ink);
}

.subscribe__inner {
  display: grid;
  gap: 3rem;
}

.subscribe__note {
  margin-top: 1.25rem;
  max-width: var(--measure);
  font-size: var(--lede-size);
  line-height: 1.5;
  color: var(--ink-soft);
}

.offer {
  border-bottom: 1px solid var(--ink);
}

.offer__row {
  display: grid;
  grid-template-columns: 6.5rem 1fr;
  align-items: baseline;
  gap: 1rem;
  padding-block: 0.9rem;
  border-top: 1px solid var(--ink);
}

.offer dt {
  color: var(--ink-soft);
}

.offer dd {
  font-size: 1.2rem;
}

.offer__price {
  font-size: clamp(2.8rem, 7vw, 4.25rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.02em;
}

.offer__unit {
  font-size: 1rem;
  color: var(--ink-soft);
}

.subscribe-form {
  margin-top: 2rem;
}

.field {
  display: grid;
  gap: 0.5rem;
}

.field__label {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.field__row {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 0.75rem 1rem;
}

.field__input {
  flex: 1 1 14rem;
  min-width: 0;
  padding: 0.75rem 0.1rem 0.6rem;
  border: 0;
  border-bottom: 2px solid var(--ink);
  border-radius: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: 1.2rem;
  color-scheme: dark;
}

.field__input[aria-invalid="true"] {
  border-bottom-color: var(--accent);
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 1.5rem;
  border: 2px solid var(--ink);
  border-radius: 0;
  background: var(--ink);
  color: var(--paper);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
}

.button:hover {
  background: transparent;
  color: var(--ink);
}

.field__error,
.field__success {
  font-size: 1rem;
  line-height: 1.4;
}

.field__error {
  font-weight: 700;
  color: var(--accent);
}

.field__success {
  padding-left: 0.75rem;
  border-left: 3px solid var(--accent);
}

@media (min-width: 900px) {
  .subscribe__inner {
    grid-template-columns: repeat(12, minmax(0, 1fr));
    column-gap: 1.5rem;
    align-items: start;
  }

  .subscribe__intro {
    grid-column: 1 / span 6;
  }

  .subscribe__offer {
    grid-column: 8 / span 5;
  }
}

/* Archive strip */
.archive {
  padding-block: 2rem 2.25rem;
  border-bottom: 3px solid var(--ink);
}

.archive__inner {
  display: grid;
  gap: 1rem;
}

.archive__list {
  display: grid;
  padding: 0;
  list-style: none;
}

.archive__list li {
  display: grid;
  gap: 0.2rem;
  padding-block: 0.75rem;
  border-top: 1px solid var(--ink);
}

.archive__issue {
  color: var(--ink-soft);
}

.archive__title {
  font-size: 1.25rem;
  font-style: italic;
}

@media (min-width: 900px) {
  .archive__inner {
    grid-template-columns: repeat(12, minmax(0, 1fr));
    column-gap: 1.5rem;
    align-items: start;
  }

  .archive__inner > .label {
    grid-column: 1 / span 3;
    padding-top: 0.75rem;
  }

  .archive__list {
    grid-column: 4 / -1;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    column-gap: 1.5rem;
  }
}

/* Footer */
.colophon {
  padding-block: 2.5rem 3rem;
}

.colophon__inner {
  display: grid;
  gap: 0.6rem;
  font-size: 0.95rem;
  color: var(--ink-soft);
}

.colophon .wordmark {
  font-size: 1.75rem;
  color: var(--ink);
}

.colophon a {
  color: var(--ink);
}

.reading-mode .cover__art {
  opacity: 0.4;
}

@media (prefers-reduced-motion: reduce) {
  .nav-list a,
  .reading-toggle__track,
  .reading-toggle__knob {
    transition: none;
  }
}

