  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.field__row {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 0.75rem 1rem;
}

.field__input {
  flex: 1 1 14rem;
  min-width: 0;
  padding: 0.75rem 0.1rem 0.6rem;
  border: 0;
  border-bottom: 2px solid var(--ink);
  border-radius: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: 1.2rem;
  color-scheme: dark;
}

.field__input[aria-invalid="true"] {
  border-bottom-color: var(--accent);
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 1.5rem;
  border: 2px solid var(--ink);
  border-radius: 0;
  background: var(--ink);
  color: var(--paper);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
}

.button:hover {
  background: transparent;
  color: var(--ink);
}

.field__error,
.field__success {
  font-size: 1rem;
  line-height: 1.4;
}

.field__error {
  font-weight: 700;
  color: var(--accent);
}

.field__success {
  padding-left: 0.75rem;
  border-left: 3px solid var(--accent);
}

