}

:root {
  --paper: #f2ede2;
  --ink: #1d1b18;
  --ink-soft: #4d4940;
  --rule: #8c8576;
  --accent: #9b4a1f;
  --measure: 36rem;
  --gutter: clamp(1.25rem, 5vw, 3.5rem);
  --body-size: 1.0625rem;
  --body-leading: 1.6;
  --lede-size: clamp(1.2rem, 2.2vw, 1.5rem);
  --font-serif: Charter, "Bitstream Charter", "Sitka Text", Cambria, Georgia, "Times New Roman", serif;
  --font-sans: "Helvetica Neue", Helvetica, Arial, "Liberation Sans", sans-serif;
  color-scheme: light;
}

/* Reading mode: larger text, looser leading, narrower measure, quieter art. */
.reading-mode {
  --body-size: 1.3125rem;
  --body-leading: 1.75;
  --lede-size: 1.6rem;
  --measure: 34em;
  --ink-soft: #2e2b25;
  --rule: #6d675b;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  background: var(--paper);
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-serif);
  font-size: var(--body-size);
  line-height: var(--body-leading);
  font-kerning: normal;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3,
p,
ol,
ul,
dl,
dd {
  margin: 0;
}

a {
  color: inherit;
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  top: -4rem;
  left: var(--gutter);
  z-index: 10;
  padding: 0.5rem 0.9rem;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--font-sans);
  font-size: 0.9rem;
  text-decoration: none;
}

.skip-link:focus {
  top: 0.75rem;
}

.wrap {
  width: calc(100% - (2 * var(--gutter)));
  max-width: 76rem;
  margin-inline: auto;
