}

.story__byline {
  margin-bottom: 0.75rem;
  font-size: 0.85rem;
  color: var(--ink-soft);
}

.story__summary {
  max-width: var(--measure);
}

@media (min-width: 900px) {
  .story-list {
    grid-template-columns: repeat(12, minmax(0, 1fr));
    column-gap: 1.5rem;
    row-gap: 3.5rem;
    align-items: start;
  }

  .story--lead {
    grid-column: 1 / span 6;
  }

  .story--lead .story__title {
    font-size: clamp(2.6rem, 5vw, 4rem);
  }

  .story--second {
    grid-column: 8 / span 5;
    margin-top: 7rem;
  }

  .story--third {
    grid-column: 3 / span 7;
  }
}

/* Subscribe: the one inverted block. Variables are swapped so children inherit the dark palette. */
.subscribe {
  --paper: #1d1b18;
  --ink: #f2ede2;
  --ink-soft: #cbc3b0;
  --rule: #6e685c;
  --accent: #e8a878;
  padding-block: clamp(3.5rem, 8vw, 6rem);
  background: var(--paper);
  color: var(--ink);
}

.subscribe__inner {
  display: grid;
  gap: 3rem;
}

.subscribe__note {
  margin-top: 1.25rem;
  max-width: var(--measure);
  font-size: var(--lede-size);
  line-height: 1.5;
  color: var(--ink-soft);
}

.offer {
  border-bottom: 1px solid var(--ink);
}

.offer__row {
  display: grid;
  grid-template-columns: 6.5rem 1fr;
  align-items: baseline;
  gap: 1rem;
  padding-block: 0.9rem;
  border-top: 1px solid var(--ink);
}

.offer dt {
  color: var(--ink-soft);
}

.offer dd {
  font-size: 1.2rem;
}

.offer__price {
  font-size: clamp(2.8rem, 7vw, 4.25rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.02em;
}

.offer__unit {
  font-size: 1rem;
  color: var(--ink-soft);
}

.subscribe-form {
  margin-top: 2rem;
}

.field {
  display: grid;
  gap: 0.5rem;
}

.field__label {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.field__row {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 0.75rem 1rem;
}

.field__input {
  flex: 1 1 14rem;
  min-width: 0;
  padding: 0.75rem 0.1rem 0.6rem;
  border: 0;
  border-bottom: 2px solid var(--ink);
  border-radius: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: 1.2rem;
  color-scheme: dark;
}

.field__input[aria-invalid="true"] {
  border-bottom-color: var(--accent);
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 1.5rem;
  border: 2px solid var(--ink);
  border-radius: 0;
  background: var(--ink);
  color: var(--paper);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
}

.button:hover {
  background: transparent;
  color: var(--ink);
}

.field__error,
.field__success {
  font-size: 1rem;
  line-height: 1.4;
}

.field__error {
  font-weight: 700;
  color: var(--accent);
}

.field__success {
  padding-left: 0.75rem;
  border-left: 3px solid var(--accent);
}

@media (min-width: 900px) {
  .subscribe__inner {
    grid-template-columns: repeat(12, minmax(0, 1fr));
    column-gap: 1.5rem;
    align-items: start;
  }

  .subscribe__intro {
    grid-column: 1 / span 6;
  }

  .subscribe__offer {
    grid-column: 8 / span 5;
  }
}

/* Archive strip */
.archive {
  padding-block: 2rem 2.25rem;
  border-bottom: 3px solid var(--ink);
}

.archive__inner {
  display: grid;
  gap: 1rem;
}

.archive__list {
  display: grid;
  padding: 0;
  list-style: none;
}

.archive__list li {
  display: grid;
  gap: 0.2rem;
  padding-block: 0.75rem;
  border-top: 1px solid var(--ink);
}

.archive__issue {
  color: var(--ink-soft);
}

.archive__title {
  font-size: 1.25rem;
  font-style: italic;
}

@media (min-width: 900px) {
  .archive__inner {
    grid-template-columns: repeat(12, minmax(0, 1fr));
    column-gap: 1.5rem;
    align-items: start;
  }

  .archive__inner > .label {
    grid-column: 1 / span 3;
    padding-top: 0.75rem;
  }

  .archive__list {
    grid-column: 4 / -1;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    column-gap: 1.5rem;
  }
}

/* Footer */
.colophon {
  padding-block: 2.5rem 3rem;
}

.colophon__inner {
  display: grid;
  gap: 0.6rem;
  font-size: 0.95rem;
  color: var(--ink-soft);
}

.colophon .wordmark {
  font-size: 1.75rem;
  color: var(--ink);
}

.colophon a {
  color: var(--ink);
}

.reading-mode .cover__art {
  opacity: 0.4;
}

@media (prefers-reduced-motion: reduce) {
  .nav-list a,
  .reading-toggle__track,
  .reading-toggle__knob {
    transition: none;
  }
}

