from html.parser import HTMLParser
import re

VOID = {"meta","link","br","input","line","use","path","rect","circle","img","hr"}

class Checker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack, self.errors, self.classes, self.ids = [], [], set(), []
    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if "class" in a: self.classes.update(a["class"].split())
        if "id" in a: self.ids.append(a["id"])
        if tag not in VOID: self.stack.append(tag)
    def handle_startendtag(self, tag, attrs):
        a = dict(attrs)
        if "class" in a: self.classes.update(a["class"].split())
        if "id" in a: self.ids.append(a["id"])
    def handle_endtag(self, tag):
        if tag in VOID: return
        if not self.stack or self.stack[-1] != tag:
            self.errors.append(f"unexpected </{tag}>, open: {self.stack[-3:]}")
        else:
            self.stack.pop()

c = Checker()
c.feed(open("index.html", encoding="utf-8").read())
print("unclosed tags:", c.stack or "none")
print("tag errors:", c.errors or "none")
dups = {i for i in c.ids if c.ids.count(i) > 1}
print("duplicate ids:", dups or "none")

css = open("styles.css", encoding="utf-8").read()
css_nc = re.sub(r"/\*.*?\*/", "", css, flags=re.S)
print("css braces balanced:", css_nc.count("{") == css_nc.count("}"))
selectors = set(re.findall(r"\.([A-Za-z][\w-]*)", css_nc))
missing = sorted(c.classes - selectors)
print("html classes with no css selector:", missing or "none")
ids_in_html = set(c.ids)
for ref in re.findall(r'href="#([\w-]+)"', open("index.html", encoding="utf-8").read()):
    if ref not in ids_in_html: print("dangling anchor:", ref)
for ref in re.findall(r'href="#([\w-]+)"', open("index.html", encoding="utf-8").read()): pass
print("anchors checked")
js = open("app.js", encoding="utf-8").read()
for i in ["reading-toggle","announcer","subscribe-form","email","email-error","email-success"]:
    if i not in ids_in_html: print("app.js refers to missing id", i)
print("js ids checked")
EOF

